-- Dzetshal Supabase Phase 3 Import
-- Run this in Supabase SQL Editor after Phase 1 and Phase 2.

alter table products add column if not exists sku text;
alter table products add column if not exists featured boolean default false;
alter table products add column if not exists notes jsonb default '{}'::jsonb;

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'products_sku_key') then
    alter table products add constraint products_sku_key unique (sku);
  end if;
end $$;

